import itertools

def solve_small(m, n):
    # All possible coins are 1 to n.
    # We want to find a matrix A of size m x m with values in 1..n.
    # Row sets X_i and column sets Y_j must be distinct.
    # There are m*m cells. Each cell can have n values.
    # n^(m*m) is too large.
    # Let's try to use backtracking or a solver.

    import random

    def get_sets(matrix, m):
        X = []
        for i in range(m):
            X.append(frozenset(matrix[i]))
        Y = []
        for j in range(m):
            Y.append(frozenset(matrix[i][j] for i in range(m)))
        return X + Y

    # Let's try random matrices for a while
    for _ in range(100000):
        matrix = [[random.randint(1, n) for _ in range(m)] for _ in range(m)]
        sets = get_sets(matrix, m)
        if len(set(sets)) == 2 * m:
            return True
    return False

for m in range(2, 5):
    for n in range(1, 10):
        if solve_small(m, n):
            print(f"m={m}, min n={n}")
            break

