import itertools

def check_m_n_exhaustive(m, n):
    # try all possible matrices? No, let's try to find cross-intersecting families.
    # We need two disjoint collections X and Y, each of size m,
    # such that for all x in X, y in Y, x intersect y is not empty.
    from itertools import combinations

    all_subsets = []
    for r in range(n + 1):
        for combo in combinations(range(n), r):
            all_subsets.append(frozenset(combo))

    import random
    for _ in range(1000000):
        sample = random.sample(all_subsets, 2 * m)
        X = sample[:m]
        Y = sample[m:]

        possible = True
        for x in X:
            for y in Y:
                if not (x & y):
                    possible = False
                    break
            if not possible: break
        if possible:
            return True
    return False

print(f"m=4, n=3: {check_m_n_exhaustive(4, 3)}")
